<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Elegir sucursal · Cupesí</title><style>body{margin:0;min-height:100vh;background:#f1f0ed;color:#231a15;font:15px Arial;display:grid;place-items:center}.box{width:min(520px,92%);background:#fff;border:1px solid #e3ded6;border-radius:18px;padding:32px;box-shadow:0 18px 50px #2b1b1312}.brand{color:#cc4a05;font-weight:700;font-size:24px}.eyebrow{color:#2f7d4f;font-size:12px;font-weight:bold;letter-spacing:.08em;margin:28px 0 8px}.box h1{font-size:30px;margin:0 0 8px}.muted{color:#6c6159}.choices{display:grid;gap:10px;margin:24px 0}.choice{display:flex;align-items:center;gap:12px;border:1px solid #e3ded6;border-radius:12px;padding:14px;cursor:pointer}.choice:has(input:checked){border-color:#cc4a05;background:#fff7f1;box-shadow:0 0 0 2px #cc4a0522}.choice input{accent-color:#cc4a05}.choice strong{display:block}.choice small{color:#6c6159}.btn{width:100%;border:0;border-radius:9px;background:#cc4a05;color:#fff;padding:13px;font-weight:bold;cursor:pointer}.logout{text-align:center;margin-top:16px}.logout button{border:0;background:none;color:#6c6159;text-decoration:underline;cursor:pointer}</style></head><body><main class="box"><div class="brand">✦ Cupesí</div><p class="eyebrow">SESIÓN DE TRABAJO</p><h1>Elige tu sucursal</h1><p class="muted">Tienes acceso a {{ $branches->count() }} sucursales. La selección define el inventario y la caja que utilizarás.</p><form method="POST" action="{{ route('branch.set') }}">@csrf<div class="choices">@foreach($branches as $branch)<label class="choice"><input type="radio" name="id_sucursal" value="{{ $branch->id_sucursal }}" @checked(session('sucursal_activa_id')==$branch->id_sucursal || ($loop->first && !session('sucursal_activa_id'))) required><span><strong>{{ $branch->nombre }}</strong><small>{{ $branch->direccion }}{{ $branch->telefono?' · '.$branch->telefono:'' }}</small></span></label>@endforeach</div><button class="btn">Continuar al sistema →</button></form><form class="logout" method="POST" action="{{ route('logout') }}">@csrf<button>Salir de la cuenta</button></form></main></body></html>
